  "loc.gpsTracker": "🛰️ GPS 追踪器",
  "loc.guide1": "安装应用 <b>“Traccar Client”</b>（App Store 或 Google Play，免费）。",
  "loc.guide2": "在应用中的 <b>设备 ID</b>（Device identifier）处填写：",
  "loc.guide3": "在 <b>服务器 URL</b> 处填写：",
  "loc.guide4": "精度 <b>中</b>，距离 <b>50 m</b>。这样应用只在你移动时发送 – 静止时不发送。若还有其他字段（间隔、心跳），将心跳关闭或设为 0。",
  "loc.guide5": "允许位置访问：<b>始终</b>，并开启 <b>精确位置</b>。",
  "loc.guide6": "打开 <b>服务 / 追踪</b> 开关并 <b>保持开启</b> – 完成。今后一切都在 pinn. 中控制：“持续发送”开或关、“单次发送”和 SOS。只要“持续发送”关闭，就没人能看到你的位置，pinn. 也不会记录路线。",
  "loc.guideIntro": "无需其他应用，“📍 共享位置”可直接在 pinn. 中使用 – 但仅在 pinn. 打开时有效。为了在 pinn. 关闭、屏幕锁定时也能发送位置，免费应用“Traccar Client”会将其直接发送到 pinn.（无需 Traccar 服务器）。iPhone 和 Android 相同。",
  "loc.h025013Watch5093": "，H02 5013、Watch 5093、Teltonika 5027。此端口必须在 FRITZ!Box 中转发到 NAS，因为追踪器是通过移动网络连接的。",
