  "loc.ifTrackerHasSos": "如果追踪器有 SOS 按钮，Traccar 一检测到追踪器的警报，pinn. 就会通过推送提醒全家（一分钟内）。",
  "loc.ifTrackerHasSos#wg": "如果追踪器有 SOS 按钮，Traccar 一检测到追踪器的警报，pinn. 就会通过推送提醒整个合租（一分钟内）。",
