  "settings.calendar.info": "每个个人资料用自己的 iCloud 或 Google 账号登录，并勾选其中的日历：“给我”只有你自己的个人资料能看到，“家庭”则由家庭里的所有人查看和使用。其他人只能看到某个家庭日历来自哪个账号——并经过遮蔽，例如 m**l@g***l.com。日程可以像往常一样创建、编辑、移动，也可以离线排队，并直接进入 iCloud 或 Google（从而进入手机）。每 15 分钟同步一次，或点“立即更新”。没有账号时，也可以只在你的 pinn. 服务器上建一个日历。通过推送的提醒和每日摘要：私人日程只发给你。",
