  "smart.guide10": "为此，设备必须能访问 pinn.（家中 Wi-Fi 或 VPN）。每个动作每个任务只运行一次；已经通过按钮启动的，自动化不会再次启动。",
  "smart.guide2": "• “获取 URL 的内容”——粘贴上面的链接",
