  "smart.guide5": "– “获取字典值”——键“eingabe”，来自“重复项目”",
  "smart.guide6": "– “获取字典值”——键“kurzbefehl”，来自“重复项目”",
  "smart.guide7": "– “运行快捷指令”——把值“kurzbefehl”选为快捷指令，把值“eingabe”选为输入",
  "smart.guide8": "2. 选项卡“自动化”→“时间”——顶部每个时间对应一个自动化，“立即运行”→“pinn Automatik”。",
  "smart.guide9": "3. 提示：另外添加“到达”（家）→“pinn Automatik”——可补上错过的动作。",
