  "smart.haIntro": "pinn. 服务器直接控制 Home Assistant——按钮在所有设备上都能用（包括 Android），自动化和“勾选时”无需快捷指令即可运行。有状态实体时，pinn. 会等到例如扫地机器人真正完成。",
