  "smart.haSearching": "正在搜索 Home Assistant …",
  "smart.haTip1": "Roborock：创建设备“扫地机器人”，在上方选择机器人（vacuum.…）——pinn. 会从地图加载房间。每个动作选“房间清洁”，并设置房间和模式（吸尘、吸尘并拖地、拖地）。“任务的房间”使用家务清洁任务的房间——名称必须与 Roborock 应用中的相同。",
  "smart.haTip2": "机器人同时充当状态：只有它回到基站后，下一个动作才会开始。",
  "smart.haTip3": "脚本会通过变量 <span class=\"font-mono\">raum</span> 收到房间名称——这样一个脚本就能处理所有房间。",
  "smart.haTip4": "灯/LED：直接在动作上设置颜色和亮度。",
  "smart.haTip5": "自动化每分钟在服务器上运行——手机上不需要自动化。",
  "smart.haToken": "长期访问令牌",
  "smart.haTokenHint": "在 Home Assistant 中：左下角你的个人资料 → 选项卡“安全” → “长期访问令牌” → “创建令牌”，然后把整个长字符串粘贴进来。前面不需要写“Bearer”——pinn. 会自己补上（写了也无妨）。令牌只保存在服务器上，绝不会发送到设备。",
